#include <cstdio>
#include <iostream>
int main() {
    FILE* file = std::tmpfile();
    if (!file) return 1;
    const unsigned char source[6]{'A','B',0,'C','D','E'};
    unsigned char result[6]{};
    const auto written = std::fwrite(source, 2, 3, file);
    bool okay = written == 3 && std::fseek(file, 0, SEEK_SET) == 0;
    const auto received = okay ? std::fread(result, 1, 6, file) : 0;
    okay = received == 6 && !std::ferror(file) && okay;
    okay = std::fclose(file) == 0 && okay;
    if (!okay) return 1;
    std::cout << "written-elements=" << written << '\n';
    std::cout << "read-bytes=" << received << '\n';
    std::cout << "embedded-zero=" << static_cast<unsigned>(result[2]) << '\n';
}

#include <iostream>
#include <string>
int main() {
    const std::string file = "ABCDEFGH";
    std::size_t kernel_position = 0;
    const auto buffer = file.substr(kernel_position, 4);
    kernel_position += buffer.size();
    std::size_t consumed = 0;
    const char first = buffer.at(consumed++);
    const char buffered_next = buffer.at(consumed);
    const char raw_next = file.at(kernel_position);
    std::cout << "first=" << first << '\n';
    std::cout << "buffered-next=" << buffered_next << '\n';
    std::cout << "raw-next=" << raw_next << '\n';
}
